<div class="container storefront"><div class="checkout-grid"><form class="profile-panel" method="post" action="<?= BASE_URL ?>?action=place-order"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><span class="eyebrow">THANH TOÁN</span><h1>Thông tin nhận hàng</h1><?php if(!empty($_SESSION['error_message'])){$m=$_SESSION['error_message'];unset($_SESSION['error_message']);echo '<p class="notice">'.e($m).'</p>';} ?><p><label>Họ tên<br><input required name="recipient_name" value="<?= e($user['full_name']??'') ?>"></label></p><p><label>Số điện thoại<br><input required name="recipient_phone" value="<?= e($user['phone']??'') ?>"></label></p><p><label>Địa chỉ<br><textarea required name="recipient_address"><?= e($user['address']??'') ?></textarea></label></p><p><label>Ghi chú<br><textarea name="note"></textarea></label></p><p>Thanh toán: <strong>COD</strong></p><button class="button primary" <?= !$cartItems?'disabled':'' ?>>Đặt hàng</button></form><aside class="profile-panel"><h2>Đơn hàng</h2><?php foreach($cartItems as $item): ?><p><?= e($item['product_name']) ?> · <?= e($item['size']) ?> × <?= e($item['quantity']) ?><br><strong><?= number_format($item['subtotal'],0,',','.') ?>đ</strong></p><?php endforeach; ?><hr><h2>Tổng: <?= number_format($totalAmount,0,',','.') ?>đ</h2></aside></div></div>
